import { ok, fail } from './result.js';
import { getCustomer, normalizeId } from './customers.js';
import { invoiceTotals } from './invoices.js';

export function balanceDue(invoice) {
  const totals = invoiceTotals(invoice);
  const paid = (invoice.payments ?? []).reduce((sum, payment) => sum + payment.amount, 0);
  return Math.max(0, totals.total - paid);
}

export function statement(customerId, invoices, asOf) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const validStatuses = ['issued', 'partially_paid'];
  const filtered = invoices
    .filter((inv) => inv.customerId === normalizedCustomerId)
    .filter((inv) => validStatuses.includes(inv.status))
    .filter((inv) => inv.issueDate <= asOf)
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate))
    .map((inv) => ({
      number: inv.number,
      issueDate: inv.issueDate,
      dueDate: inv.dueDate,
      total: invoiceTotals(inv).total,
      due: balanceDue(inv),
    }));

  const totalDue = filtered.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId: normalizedCustomerId,
    invoices: filtered,
    totalDue,
  });
}

