import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { statement } from '../src/statements.js';

test('statement returns customer not found for unknown customer', () => {
  const r = statement('C-999', [], '2025-10-31');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('statement returns empty invoices for customer with no issued invoices', () => {
  const r = statement('C-001', [], '2025-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.totalDue, 0);
});

test('statement includes single issued invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement('C-001', [issued], '2025-10-31');
  assert.equal(r3.ok, true);
  assert.equal(r3.value.invoices.length, 1);
  assert.equal(r3.value.invoices[0].number, 'INV-2025-0001');
  assert.equal(r3.value.invoices[0].issueDate, '2025-10-07');
});

test('statement includes dueDate in invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement('C-001', [issued], '2025-10-31');
  assert.equal(r3.value.invoices[0].dueDate, '2025-10-21');
});

test('statement includes total in invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement('C-001', [issued], '2025-10-31');
  assert.ok(r3.value.invoices[0].total > 0);
});

test('statement includes due (unpaid balance) in invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement('C-001', [issued], '2025-10-31');
  assert.equal(r3.value.invoices[0].due, r3.value.invoices[0].total);
});

test('statement calculates due after partial payment', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = require('../src/invoices.js').invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);
  const r3 = recordPayment(issued, { amount: half, date: '2025-10-08' });
  const paid = r3.value;

  const r4 = statement('C-001', [paid], '2025-10-31');
  assert.equal(r4.value.invoices[0].due, totals.total - half);
});

test('statement excludes draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;

  const r2 = statement('C-001', [invoice], '2025-10-31');
  assert.equal(r2.value.invoices.length, 0);
});

test('statement excludes invoices after asOf date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement('C-001', [issued], '2025-10-06');
  assert.equal(r3.value.invoices.length, 0);
});

test('statement includes invoices with issueDate equal to asOf', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement('C-001', [issued], '2025-10-07');
  assert.equal(r3.value.invoices.length, 1);
});

test('statement sorts invoices by issueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);
  const inv3 = issueInvoice(r3.value, ['INV-2025-0001', 'INV-2025-0002']);

  const r4 = statement('C-001', [inv1.value, inv2.value, inv3.value], '2025-10-31');
  assert.equal(r4.value.invoices[0].issueDate, '2025-10-07');
  assert.equal(r4.value.invoices[1].issueDate, '2025-10-10');
  assert.equal(r4.value.invoices[2].issueDate, '2025-10-15');
});

test('statement sums totalDue from all invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);

  const r3 = statement('C-001', [inv1.value, inv2.value], '2025-10-31');
  const expectedTotal = r3.value.invoices[0].due + r3.value.invoices[1].due;
  assert.equal(r3.value.totalDue, expectedTotal);
});

test('statement excludes other customers invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);

  const r3 = statement('C-001', [inv1.value, inv2.value], '2025-10-31');
  assert.equal(r3.value.invoices.length, 1);
  assert.equal(r3.value.invoices[0].number, 'INV-2025-0001');
});

test('statement handles partially_paid status', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = require('../src/invoices.js').invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);
  const r3 = recordPayment(issued, { amount: half, date: '2025-10-08' });
  const partially = r3.value;

  const r4 = statement('C-001', [partially], '2025-10-31');
  assert.equal(r4.value.invoices.length, 1);
  assert.equal(r4.value.invoices[0].due, totals.total - half);
});

test('statement excludes paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = require('../src/invoices.js').invoiceTotals(issued);
  const r3 = recordPayment(issued, { amount: totals.total, date: '2025-10-08' });
  const paid = r3.value;

  const r4 = statement('C-001', [paid], '2025-10-31');
  assert.equal(r4.value.invoices.length, 0);
});

test('statement normalizes customer ID', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement(' c-001 ', [issued], '2025-10-31');
  assert.equal(r3.ok, true);
  assert.equal(r3.value.customerId, 'C-001');
  assert.equal(r3.value.invoices.length, 1);
});

test('statement with voucher applied', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME', amount: 1000 });
  const vouched = r2.value;
  const r3 = issueInvoice(vouched, []);
  const issued = r3.value;
  const totals = require('../src/invoices.js').invoiceTotals(issued);

  const r4 = statement('C-001', [issued], '2025-10-31');
  assert.equal(r4.value.invoices[0].total, totals.total);
});

test('statement returns customer ID in response', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = statement('C-001', [issued], '2025-10-31');
  assert.equal(r3.value.customerId, 'C-001');
});

test('statement with multiple invoices and mixed payment status', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });

  const inv1 = issueInvoice(r1.value, []);
  const inv2 = issueInvoice(r2.value, ['INV-2025-0001']);
  const inv3 = issueInvoice(r3.value, ['INV-2025-0001', 'INV-2025-0002']);

  const totals1 = require('../src/invoices.js').invoiceTotals(inv1.value);
  const totals2 = require('../src/invoices.js').invoiceTotals(inv2.value);

  const inv2Paid = recordPayment(inv2.value, { amount: Math.floor(totals2.total / 2), date: '2025-10-12' }).value;

  const r4 = statement('C-001', [inv1.value, inv2Paid, inv3.value], '2025-10-31');
  assert.equal(r4.value.invoices.length, 3);
  assert.equal(r4.value.invoices[0].due, totals1.total);
  assert.equal(r4.value.invoices[1].due, Math.ceil(totals2.total / 2));
  assert.ok(r4.value.totalDue > 0);
});

